namespace CustomPhysics2D;

/// <summary>
/// Contact information generated by narrow-phase collision detection.
/// </summary>
public struct CollisionManifold
{
    public bool HasCollision;

    /// <summary>
    /// Collision normal pointing from body A toward body B.
    /// </summary>
    public Vector2 Normal;

    /// <summary>
    /// Amount by which the shapes overlap along the collision normal.
    /// </summary>
    public float PenetrationDepth;

    /// <summary>
    /// Number of contact points.
    /// </summary>
    public int ContactCount;

    public Vector2 Contact1;
    public Vector2 Contact2;

    public static CollisionManifold None => new()
    {
        HasCollision = false,
        Normal = Vector2.Zero,
        PenetrationDepth = 0f,
        ContactCount = 0
    };
}